\item[S2] Mini-Workshop: Standard Subspaces in Quantum Field Theory and Representation Theory (2023), Oberwolfach Reports, DOI 10.4171/owr/2023/50, pp. 2851--2901. Original report and mathematical context.
\url{https://doi.org/10.4171/owr/2023/50}.
\end{itemize}
